/**
 * SensorManager - Manages sensor scheduling and updates
 *
 * Holds and updates all sensors attached to an AI agent.
 * Supports variadic add/remove operations.
 *
 * **Usage**
 *
 * ```js
 * const manager = new SensorManager();
 *
 * // Add multiple sensors
 * manager.add(
 *   new VisionSensor({ fov: 90 }),
 *   new DamageSensor()
 * );
 *
 * // Update each frame
 * manager.update(body, state, memory, delta);
 *
 * // Remove a sensor
 * manager.remove(sensor);
 * ```
 *
 * @module @three-blocks/pro/ai/SensorManager
 * @class SensorManager
 * @short Manages sensor scheduling
 * @category AI
 * @private
 * @tags AI, Sensor, Manager
 */
export class SensorManager {
    /**
     * Array of managed sensors.
     * @type {Sensor[]}
     * @private
     */
    private _sensors;
    /**
     * Map of sensors by ID for fast lookup.
     * @type {Map<string, Sensor>}
     * @private
     */
    private _sensorMap;
    /**
     * Add one or more sensors.
     *
     * @param {...Sensor} sensors - Sensors to add.
     * @returns {SensorManager} This instance for chaining.
     */
    add(...sensors: Sensor[]): SensorManager;
    /**
     * Remove a sensor.
     *
     * @param {Sensor} sensor - Sensor to remove.
     * @returns {boolean} True if sensor was removed.
     */
    remove(sensor: Sensor): boolean;
    /**
     * Remove a sensor by ID.
     *
     * @param {string} id - Sensor ID to remove.
     * @returns {boolean} True if sensor was removed.
     */
    removeById(id: string): boolean;
    /**
     * Get a sensor by ID.
     *
     * @param {string} id - Sensor ID.
     * @returns {Sensor|undefined} The sensor or undefined.
     */
    get(id: string): Sensor | undefined;
    /**
     * Get a sensor by type.
     *
     * @param {string} type - Sensor type.
     * @returns {Sensor|undefined} First sensor of type or undefined.
     */
    getByType(type: string): Sensor | undefined;
    /**
     * Get all sensors of a type.
     *
     * @param {string} type - Sensor type.
     * @returns {Sensor[]} Array of matching sensors.
     */
    getAllByType(type: string): Sensor[];
    /**
     * Check if a sensor exists.
     *
     * @param {Sensor|string} sensorOrId - Sensor or ID to check.
     * @returns {boolean} True if sensor exists.
     */
    has(sensorOrId: Sensor | string): boolean;
    /**
     * Update all sensors.
     *
     * @param {Object} body - The physics body.
     * @param {State} state - The perception state.
     * @param {Memory} memory - The time-decaying memory.
     * @param {number} delta - Time delta in seconds.
     */
    update(body: any, state: State, memory: Memory, delta: number): void;
    /**
     * Get the number of sensors.
     *
     * @returns {number} Number of sensors.
     */
    get count(): number;
    /**
     * Get all sensors.
     *
     * @returns {Sensor[]} Array of all sensors.
     */
    get sensors(): Sensor[];
    /**
     * Serialize all sensors for worker transfer.
     *
     * @returns {Object[]} Array of serialized sensor configs.
     */
    serialize(): any[];
    /**
     * Clear all sensors.
     *
     * @returns {SensorManager} This instance for chaining.
     */
    clear(): SensorManager;
    /**
     * Dispose of all sensors and clear.
     */
    dispose(): void;
}
